<script setup>
import { ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import RepairmentForm from '@/features/repairment-form/RepairmentForm.vue'; import FeedbackMessage from '@/components/FeedbackMessage.vue'; import { apiRequest } from '@/lib/api'; const route=useRoute(),router=useRouter(),error=ref(''),busy=ref(false); async function save(form){busy.value=true;try{const r=await apiRequest(`/api/repairments/item/${route.params.itemId}`,{method:'POST',body:JSON.stringify(form)});await router.push(`/repairments/${r._id}`)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><main class="page editor-page"><RouterLink class="back-link" :to="`/items/${route.params.itemId}`">← Item details</RouterLink><span class="eyebrow eyebrow--light">New repairment</span><h1>Open a repairment record.</h1><FeedbackMessage :message="error" /><RepairmentForm :busy="busy" @submit="save" /></main></template>
